params2 = {"query": "biocontainers/python openpyxl", "limit": 5}
r2 = requests.get(url, params=params2)
if r2.status_code == 200:
    for result in r2.json().get('results', []):
        print(f"  {result.get('namespace')}/{result.get('name')}: {result.get('description', '')}")

# Search known BioContainer for python packages
print("\n--- Direct tag check ---")
# Check common python BioContainers
for img in ["biocontainers/python", "biocontainers/python-3.9", "biocontainers/python-3.10"]:
    tags_url = f"https://quay.io/api/v1/repository/{img}/tag"
    r = requests.get(tags_url, params={"limit": 3, "onlyActiveTags": "true"})
    if r.status_code == 200:
        for tag in r.json().get('tags', [])[:3]:
            print(f"  {img}:{tag['name']}")
EOF

