            continue
        if 'Trio_Status' in ds['name'] or 'CHIP_Genes' in ds['name']:
            continue
        if ds['extension'] == 'zip':
            try:
                gi.histories.update_dataset(hist_id, ds['id'], data_type='xlsx')
                fixed += 1
            except Exception as e:
                print(f"Failed to fix {ds['name']}: {e}")
    print(f"Fixed {fixed} files to xlsx datatype")

