import os, requests, time

key_file = os.environ.get('GALAXY_API_KEY_FILE', '')
if key_file:
    with open(key_file) as f:
        api_key = f.read().strip()
else:
    api_key = os.environ.get('GALAXY_API_KEY', '')

base_url = 'https://usegalaxy.org'
headers = {'x-api-key': api_key, 'Content-Type': 'application/json'}

hist_id = 'bbd44e69cb8906b572ac24013c52bcf3'

# Approach: Use the history contents API to update the HDA
# endpoint: /api/histories/{hist_id}/contents/{hda_id}

# Update all zip-labeled files
zip_updated = 0
for ds_page in range(1, 5):
    r = requests.get(
        f"{base_url}/api/histories/{hist_id}/contents",
        headers=headers,
        params={'offset': (ds_page-1)*100, 'limit': 100}
    )
    if r.status_code != 200:
        break
    for ds in r.json():
        if ds.get('deleted'):
            continue
        name = ds.get('name', '')
        if not name.endswith('.xlsx'):
            continue
        if 'Trio_Status' in name or 'CHIP_Genes' in name:
            continue
        if ds.get('extension') == 'xlsx':
            continue

        # Found a zip-labeled file
        hda_id = ds['id']
        url = f"{base_url}/api/histories/{hist_id}/contents/{hda_id}"
        payload = {'extension': 'xlsx', 'file_ext': 'xlsx', 
                   'data_type': 'galaxy.datatypes.binary.ExcelXlsx'}
        r2 = requests.put(url, headers=headers, json=payload)
        if r2.status_code == 200:
            zip_updated += 1
        else:
            print(f"Failed: {name}: {r2.status_code}")
        time.sleep(0.05)  # Rate limit

print(f"Updated {zip_updated} files to xlsx")

# Verify
r = requests.get(
    f"{base_url}/api/histories/{hist_id}/contents",
    headers=headers,
    params={'limit': 200}
)
zip_remaining = 0
xlsx_count = 0
for ds in r.json():
    name = ds.get('name', '')
    if not name.endswith('.xlsx'):
        continue
    if 'Trio_Status' in name or 'CHIP_Genes' in name:
        continue
    if ds.get('extension') in ('zip', 'CompressedZipArchive'):
        zip_remaining += 1
    elif ds.get('extension') == 'xlsx':
        xlsx_count += 1

print(f"After update: {zip_remaining} zip, {xlsx_count} xlsx among variant files")
PYEOF

